// TIM2 tick = 84 MHz / (83 + 1) = 1 MHz.
// Passive piezo: PA0 -> +, GND -> -. Enable the simulator sound button.
void playNote(uint32_t frequency, uint32_t duration) {
  HAL_TIM_PWM_Stop(&htim2, TIM_CHANNEL_1);
  if (frequency > 0) {
    uint32_t period = 1000000 / frequency;
    __HAL_TIM_SET_AUTORELOAD(&htim2, period - 1);
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, period / 2);
    __HAL_TIM_SET_COUNTER(&htim2, 0);
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);
    printf("Passive buzzer: %lu Hz\n", frequency);
  } else {
    printf("Passive buzzer: rest\n");
  }
  HAL_Delay(duration);
  HAL_TIM_PWM_Stop(&htim2, TIM_CHANNEL_1);
}

int main(void) {
  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  MX_TIM2_Init();
  /* USER CODE BEGIN 2 */
  HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);
  /* USER CODE END 2 */
  while (1) {
    /* USER CODE BEGIN 3 */
    uint32_t notes[8] = {523, 587, 659, 698, 784, 880, 988, 1047};
    for (int i = 0; i < 8; i++) {
      playNote(notes[i], 350);
      playNote(0, 80);
    }
    playNote(0, 600);
    /* USER CODE END 3 */
  }
}

